#define main historical_main
#include "../tissue-cuda/main.cu"
#undef main
#include <vector>
int main(){const int dim=4,nnt=dim*dim*dim,nntDev=32768,step=4;std::vector<int>pts(3*nntDev,0);std::vector<float>g(2*nntDev),b(2*nntDev),prev(nntDev,0),qt(nntDev,0),cpu(nntDev,0),got(nntDev,0);for(int i=0;i<nnt;i++){pts[i]=i%dim;pts[nnt+i]=(i/dim)%dim;pts[2*nnt+i]=i/(dim*dim);prev[i]=float(i%9-4)/8;qt[i]=float(i%13-6)/16;}for(int i=0;i<2*nntDev;i++){g[i]=float(i%17+1)/32;b[i]=float(i%11+1)/64;}reference(pts.data(),g.data(),b.data(),cpu.data(),prev.data(),qt.data(),nnt,nntDev,step,2);int*dp;float*dg,*db,*dc,*dprev,*dqt;cudaMalloc(&dp,pts.size()*sizeof(int));cudaMalloc(&dg,g.size()*4);cudaMalloc(&db,b.size()*4);cudaMalloc(&dc,nntDev*4);cudaMalloc(&dprev,nntDev*4);cudaMalloc(&dqt,nntDev*4);cudaMemcpy(dp,pts.data(),pts.size()*sizeof(int),cudaMemcpyHostToDevice);cudaMemcpy(dg,g.data(),g.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(db,b.data(),b.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(dprev,prev.data(),nntDev*4,cudaMemcpyHostToDevice);cudaMemcpy(dqt,qt.data(),nntDev*4,cudaMemcpyHostToDevice);int failed=0;double ma=0;for(int check=1;check<=10;check++){cudaMemset(dc,0,nntDev*4);tissue<<<1,256>>>(dp,dg,db,dc,dprev,dqt,nnt,nntDev,step,2);cudaError_t status=cudaDeviceSynchronize();cudaMemcpy(got.data(),dc,nntDev*4,cudaMemcpyDeviceToHost);int mismatches=0;double maxerr=0;for(int i=0;i<nnt;i++){double e=fabs(double(got[i])-cpu[i]);maxerr=fmax(maxerr,e);mismatches+=e>1e-4;}ma=fmax(ma,maxerr);failed+=mismatches>0;printf("TISSUE_NATIVE_STEP4_WITNESS check=%d cuda_status=%d mismatches=%d checked=%d max_abs_error=%.12g\n",check,int(status),mismatches,nnt,maxerr);}printf("TISSUE_NATIVE_STEP4_SUMMARY failed_checks=%d total_checks=10 max_abs_error=%.12g\n",failed,ma);cudaFree(dp);cudaFree(dg);cudaFree(db);cudaFree(dc);cudaFree(dprev);cudaFree(dqt);return 0;}
